function lineEdits(before,after){
 const a=before.split("\n"),b=after.split("\n");let prefix=0;while(prefix<a.length&&prefix<b.length&&a[prefix]===b[prefix])prefix++;
 let ae=a.length,be=b.length;while(ae>prefix&&be>prefix&&a[ae-1]===b[be-1]){ae--;be--;}
 const aa=a.slice(prefix,ae),bb=b.slice(prefix,be),width=bb.length+1,dp=new Uint32Array((aa.length+1)*width);
 for(let i=aa.length-1;i>=0;i--)for(let j=bb.length-1;j>=0;j--)dp[i*width+j]=aa[i]===bb[j]?1+dp[(i+1)*width+j+1]:Math.max(dp[(i+1)*width+j],dp[i*width+j+1]);
 let i=0,j=0,edit=null,out=[];const flush=()=>{if(edit){out.push(edit);edit=null;}};
 while(i<aa.length||j<bb.length){
  if(i<aa.length&&j<bb.length&&aa[i]===bb[j]){flush();i++;j++;continue;}
  if(!edit)edit={baseStartLine:prefix+i+1,newStartLine:prefix+j+1,removed:[],added:[]};
  if(j<bb.length&&(i===aa.length||dp[i*width+j+1]>=dp[(i+1)*width+j]))edit.added.push(bb[j++]);else edit.removed.push(aa[i++]);
 }flush();return out;
}
